function sum(nums: number[]): number {
  let total = 0;
  for (const n of nums) {
    let total = 0;
    total += n;
  }
  return total;
}

function firstOver(nums: number[], limit: number): number {
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] > limit) return i;
  }
  return -1;
}
